with.command:
set -eu
head=$(git -C "$REPO" rev-parse --verify "refs/heads/$BRANCH^{commit}") || { echo "the branch $BRANCH does not exist in this tree" >&2; exit 1; }
base=$(git -C "$REPO" merge-base "$BASE" "$head") || { echo "$BRANCH shares no history with $BASE" >&2; exit 1; }
case "$MANDATE_FILE" in /*) ;; *) echo "the mandate file is not an absolute path: $MANDATE_FILE" >&2; exit 1 ;; esac
[ -r "$MANDATE_FILE" ] || { echo "the mandate file $MANDATE_FILE cannot be read" >&2; exit 1; }
mandate_digest=$(shasum -a 256 < "$MANDATE_FILE" | awk '{ print $1 }')
manifest=$(git -C "$REPO" show "$head:docs/gates.md") || { echo "commit $head carries no docs/gates.md: there is no gate manifest to bind the verdict to" >&2; exit 1; }
gates_digest=$(printf '%s\n' "$manifest" | shasum -a 256 | awk '{ print $1 }')
pin="refs/sailor/reviews/$BRANCH/$head"
if pinned=$(git -C "$REPO" rev-parse --verify --quiet "$pin"); then
    [ "$pinned" = "$head" ] || { echo "$pin already points at $pinned" >&2; exit 1; }
else
    git -C "$REPO" update-ref "$pin" "$head" ""
fi
printf '{"head":"%s","base_commit":"%s","mandate_digest":"%s","gates_digest":"%s","pin":"%s","pinned_at":%s}' \
    "$head" "$base" "$mandate_digest" "$gates_digest" "$pin" "$(date +%s)"

set -eu
short=$(printf '%s' "$HEAD_COMMIT" | cut -c1-12)
tree="$(dirname "$REPO")/$(basename "$REPO")-worktrees/review-$short"
if [ -e "$tree" ]; then
    at=$(git -C "$tree" rev-parse HEAD) || { echo "$tree exists and is not a checkout" >&2; exit 1; }
    [ "$at" = "$HEAD_COMMIT" ] || { echo "$tree stands at $at, not the pinned $HEAD_COMMIT" >&2; exit 1; }
    tree_status=$(git -C "$tree" status --porcelain) || { echo "cannot read the status of $tree" >&2; exit 2; }
    [ -z "$tree_status" ] || { echo "$tree carries changes: it is not the pinned commit any more" >&2; exit 1; }
else
    mkdir -p "$(dirname "$tree")"
    git -C "$REPO" worktree add --detach --lock --reason "review of $HEAD_COMMIT" "$tree" "$HEAD_COMMIT" >&2
fi
at=$(git -C "$tree" rev-parse HEAD)
[ "$at" = "$HEAD_COMMIT" ] || { echo "the reviewer tree stands at $at, not $HEAD_COMMIT" >&2; exit 1; }
printf '{"tree":"%s","head":"%s"}' "$tree" "$at"

set -eu
sailor_now=$(shasum -a 256 < "$SAILOR_BIN") || { echo "cannot read the sailor the review was to be closed with, $SAILOR_BIN" >&2; exit 2; }
[ "${sailor_now%% *}" = "$SAILOR_SHA" ] || { echo "the sailor at $SAILOR_BIN changed while the review was open (sha256 ${sailor_now%% *}, not $SAILOR_SHA): the verdict it recorded is not taken" >&2; exit 2; }
printf '%s' "$VERDICT" | HEAD_COMMIT="$HEAD_COMMIT" python3 -c '
import json, os, sys
verdict = json.loads(sys.stdin.read())
if not isinstance(verdict, dict):
    sys.exit("the verdict is not one JSON object")
if verdict.get("commit") != os.environ["HEAD_COMMIT"]:
    sys.exit("the verdict names commit %r, not the pinned %s" % (verdict.get("commit"), os.environ["HEAD_COMMIT"]))
if verdict.get("verdict") not in ("clean", "findings"):
    sys.exit("the verdict is neither clean nor findings")
findings = verdict.get("findings", [])
checked = verdict.get("checked", [])
if not isinstance(findings, list) or not isinstance(checked, list):
    sys.exit("findings and checked are lists")
if verdict["verdict"] == "findings" and not findings:
    sys.exit("a verdict of findings names none")
if not checked:
    sys.exit("the verdict lists nothing it checked")
print(json.dumps({"commit": verdict["commit"], "verdict": verdict["verdict"], "findings": len(findings), "checked": len(checked)}))
'
